#!/usr/bin/env node
/**
 * Validate the fumadocs navigation files under docs/ and spec/ (AISDLC-854).
 *
 * Every page named in a meta.json must resolve to a sibling `<page>.md`,
 * a sub-directory, or (for `index`) an index.md / README.md. Separators
 * (`---Title---`) are allowed. `rfc-registry` is generated by the site build.
 * Entries may not escape the meta.json directory.
 *
 * Reverse direction (AISDLC-1315): every `.md`/`.mdx` file directly in a
 * NAV_FILES directory, and every sub-directory with its own NAV_FILES entry,
 * must be named by that directory's meta.json or recorded in UNLISTED.
 *
 * Usage: node scripts/check-docs-nav.mjs
 */
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { join, dirname, resolve, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

export const NAV_FILES = [
  'docs/meta.json',
  'docs/getting-started/meta.json',
  'docs/concepts/meta.json',
  'docs/tutorials/meta.json',
  'docs/api-reference/meta.json',
  'docs/whitepapers/meta.json',
  'spec/meta.json',
];

/** Published paths deliberately absent from navigation; each needs a reason. */
export const UNLISTED = {
  'docs/whitepapers':
    'Rendered by the site with its own code (white papers and PDFs); docs/meta.json omission is unconfirmed, see AISDLC-1315.',
  'docs/concepts/autonomous-orchestrator.md': 'Retired page, kept for inbound links.',
  'docs/concepts/operator-tui.md': 'Retired page, kept for inbound links.',
};

const GENERATED = new Set(['docs/meta.json:rfc-registry']);

export function checkNav(root, files = NAV_FILES, unlisted = UNLISTED) {
  const errors = [];
  const named = new Set();
  for (const u of Object.keys(unlisted)) {
    if (!existsSync(join(root, u))) errors.push(`UNLISTED: "${u}" does not exist`);
  }
  for (const rel of files) {
    const file = join(root, rel);
    if (!existsSync(file)) {
      errors.push(`${rel}: missing`);
      continue;
    }
    let meta;
    try {
      meta = JSON.parse(readFileSync(file, 'utf8'));
    } catch (e) {
      errors.push(`${rel}: invalid JSON (${e.message})`);
      continue;
    }
    if (typeof meta.title !== 'string' || !Array.isArray(meta.pages)) {
      errors.push(`${rel}: needs string "title" and array "pages"`);
      continue;
    }
    const dir = dirname(file);
    const dirRel = dirname(rel).split('\\').join('/');
    for (const page of meta.pages) {
      if (typeof page !== 'string') {
        errors.push(`${rel}: non-string page entry`);
        continue;
      }
      if (typeof page === 'string') {
        named.add(`${dirRel}/${page}`);
        const u = [`${dirRel}/${page}`, `${dirRel}/${page}.md`, `${dirRel}/${page}.mdx`].find(
          (k) => k in unlisted,
        );
        if (u) errors.push(`UNLISTED: "${u}" is also named by ${rel}`);
      }
      if (/^---.*---$/.test(page) || GENERATED.has(`${rel}:${page}`)) continue;
      const target = resolve(dir, page);
      const r = relative(root, target);
      if (r.startsWith('..') || !/^(docs|spec)(\/|$)/.test(r.split('\\').join('/'))) {
        errors.push(`${rel}: "${page}" points outside docs/ or spec/`);
        continue;
      }
      const ok =
        page === 'index'
          ? ['index.md', 'README.md'].some((n) => existsSync(join(dir, n)))
          : existsSync(`${target}.md`) || (existsSync(target) && statSync(target).isDirectory());
      if (!ok) errors.push(`${rel}: page "${page}" does not exist`);
    }
  }
  const navDirs = new Set(files.map((f) => dirname(f).split('\\').join('/')));
  for (const rel of files) {
    const dirRel = dirname(rel).split('\\').join('/');
    const dir = join(root, dirRel);
    if (!existsSync(join(root, rel)) || !existsSync(dir)) continue;
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const key = `${dirRel}/${entry.name}`;
      let stem;
      if (entry.isDirectory()) {
        if (!navDirs.has(key)) continue;
        stem = entry.name;
      } else if (/\.mdx?$/.test(entry.name)) {
        stem = entry.name.replace(/\.mdx?$/, '');
        if (stem === 'README' && named.has(`${dirRel}/index`)) continue;
      } else continue;
      if (!named.has(`${dirRel}/${stem}`) && !(key in unlisted)) {
        errors.push(`${key}: not named by ${rel} or UNLISTED`);
      }
    }
  }
  return errors;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
  const errors = checkNav(root);
  if (errors.length) {
    for (const e of errors) console.error(`check-docs-nav: ${e}`);
    process.exit(1);
  }
  console.log(`check-docs-nav: ${NAV_FILES.length} navigation files valid`);
}
